namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;
    private readonly Lock _lock = new();

    // Seed data that is always returned by GetNotificationsAsync.
    private readonly List<Notification> _notifications =
    [
        new(1, "Welcome to the app!", new DateTime(2026, 6, 17, 8, 0, 0, DateTimeKind.Utc)),
        new(2, "Your profile was updated.", new DateTime(2026, 6, 17, 9, 30, 0, DateTimeKind.Utc)),
        new(3, "New feature: dark mode is available.", new DateTime(2026, 6, 17, 12, 0, 0, DateTimeKind.Utc)),
    ];

    /// <summary>Returns a snapshot of all notifications so far.</summary>
    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>Simulates checking for new notifications.
    /// Produces a new notification roughly every other call.</summary>
    public Task<List<Notification>> CheckForNewNotificationsAsync()
    {
        lock (_lock)
        {
            if (Random.Shared.NextDouble() > 0.5)
            {
                var n = new Notification(
                    _nextId++,
                    $"Something happened at {DateTime.UtcNow:T} UTC",
                    DateTime.UtcNow);
                _notifications.Add(n);
                return Task.FromResult<List<Notification>>([n]);
            }

            return Task.FromResult<List<Notification>>([]);
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("g")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification>? notifications;
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // Restore from prerender state if available; otherwise load once.
        if (PersistedNotifications is not null)
        {
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = await NotificationService.GetNotificationsAsync();
            PersistedNotifications = notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // Only runs in the interactive runtime — never during prerender.
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
                var newItems = await NotificationService.CheckForNewNotificationsAsync();
                if (newItems.Count > 0 && notifications is not null)
                {
                    notifications.AddRange(newItems);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

